  `id` int(10) UNSIGNED NOT NULL,
  `name` varchar(50) DEFAULT NULL,
  `network` varchar(50) DEFAULT NULL,
  `wallet_type` varchar(50) DEFAULT NULL,
  `category` varchar(50) DEFAULT NULL,
  `description` varchar(1024) DEFAULT NULL,
  `transaction_status` varchar(15) DEFAULT NULL,
  `wallet_number` varchar(50) DEFAULT NULL,
  `amount` float(10,2) DEFAULT 0.00,
  `debit` float(10,2) DEFAULT 0.00,
  `credit` float(10,2) DEFAULT 0.00,
  `balance` float(10,2) DEFAULT 0.00,
  `assigned` varchar(100) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  `disabled` tinyint(1) UNSIGNED DEFAULT 0,
  `deleted` tinyint(1) UNSIGNED DEFAULT 0,
  `date_created` datetime DEFAULT NULL,
  `date_updated` datetime DEFAULT NULL,
  `date_deleted` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

